// sw.js: quest_log desktop's service worker (generated by vite.config.ts; don't edit).
// Keeps a copy of every file of this build so the app works offline.
const CACHE = 'quest_log_desktop-b68c4dfae848';
const INDEX = '/quest_log_desktop/';
const FILES = [
  "/quest_log_desktop/",
  "/quest_log_desktop/assets/JetBrainsMono-Bold-DxpIpPQ0.woff2",
  "/quest_log_desktop/assets/JetBrainsMono-Medium-XfjSvX7f.woff2",
  "/quest_log_desktop/assets/JetBrainsMono-Regular-CtxPQfgF.woff2",
  "/quest_log_desktop/assets/index-3HZgIdnY.css",
  "/quest_log_desktop/assets/index-BGIH4R2F.js",
  "/quest_log_desktop/icons/icon-192.png",
  "/quest_log_desktop/icons/icon-512.png",
  "/quest_log_desktop/icons/maskable-512.png",
  "/quest_log_desktop/manifest.webmanifest"
];

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('quest_log_desktop-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
  if (request.mode === 'navigate') {
    event.respondWith(fetch(request).catch(() => caches.match(INDEX)));
    return;
  }
  event.respondWith(caches.match(request).then((hit) => hit || fetch(request)));
});
